SELECT 
FROM wx_daily_vote_receipt
WHERE appid = #{appid,jdbcType=VARCHAR}
  AND (message_key = #{messageKey,jdbcType=VARCHAR}
       OR (user_key = #{userKey,jdbcType=VARCHAR}
           AND question_id = #{questionId,jdbcType=BIGINT}))
ORDER BY id
LIMIT 2
FOR UPDATE

SELECT id, receipt_id, appid, message_key, user_key, request_fingerprint,
       question_id, create_time, update_time
FROM wx_daily_vote_message_receipt
WHERE appid = #{appid,jdbcType=VARCHAR}
  AND message_key = #{messageKey,jdbcType=VARCHAR}
LIMIT 1

mapper.update:
UPDATE wx_daily_vote_receipt
SET status = 'COMPLETED',
    request_fingerprint = #{requestFingerprint,jdbcType=VARCHAR},
    correct = #{correct,jdbcType=INTEGER},
    point_awarded = #{pointAwarded,jdbcType=INTEGER},
    reply_content = #{replyContent,jdbcType=VARCHAR},
    update_time = #{updateTime,jdbcType=BIGINT}
WHERE id = #{id,jdbcType=BIGINT}
  AND processor_token = #{processorToken,jdbcType=VARCHAR}
  AND status = 'PROCESSING'
